WITH enriched AS (SELECT id, country, city, rating, STDDEV_SAMP(rating) OVER (PARTITION BY country) country_stddev_samp_rating, NTILE(4) OVER (ORDER BY rating, id) rating_bucket, FIRST_VALUE(city) IGNORE NULLS OVER (PARTITION BY country ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_city, AVG(rating) OVER (PARTITION BY city, country ORDER BY rating, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) rating_avg_5_prior, ROUND(rating / SUM(rating) OVER (PARTITION BY country), 4) rating_share FROM suppliers) SELECT id, country, city, rating, country_stddev_samp_rating, rating_avg_5_prior, rating_share FROM enriched ORDER BY country_stddev_samp_rating NULLS LAST
